package com.bank.consistency.routing;

import org.springframework.stereotype.Component;
import java.util.concurrent.ConcurrentHashMap;

@Component
public class SessionConsistencyRegistry {
    // user/session → timestamp until which their reads MUST hit the primary
    private final ConcurrentHashMap<String, Long> readFromPrimaryUntil = new ConcurrentHashMap<>();
    private final long windowMs = 3000;

    // Call right after a user's write: pin their reads to the primary for the window.
    public void markWrite(String userId) {
        readFromPrimaryUntil.put(userId, System.currentTimeMillis() + windowMs);
    }

    // True if this user must read from the primary right now (read-your-own-writes).
    public boolean mustReadPrimary(String userId) {
        Long until = readFromPrimaryUntil.get(userId);
        return until != null && System.currentTimeMillis() < until;
    }
}
