package com.bank.consistency.service;

import com.bank.consistency.routing.SessionConsistencyRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferService {
    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private final JdbcTemplate primary;
    private final SessionConsistencyRegistry registry;

    public TransferService(JdbcTemplate primary, SessionConsistencyRegistry registry) {
        this.primary = primary; this.registry = registry;
    }

    // Writes ALWAYS go to the primary. Then pin this user's reads to the primary.
    @Transactional
    public void transfer(String userId, String fromId, String toId, BigDecimal amount) {
        primary.update("UPDATE accounts SET balance = balance - ? WHERE account_id = ?", amount, fromId);
        primary.update("UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, toId);
        registry.markWrite(userId);   // read-your-own-writes guarantee starts now
        log.info("Transfer {} by user {} committed on primary; reads pinned to primary", amount, userId);
    }
}
