package com.bank.consistency.service;

import com.bank.consistency.routing.SessionConsistencyRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
public class BalanceReadService {
    private static final Logger log = LoggerFactory.getLogger(BalanceReadService.class);
    private final JdbcTemplate primary;
    private final JdbcTemplate replica;
    private final SessionConsistencyRegistry registry;

    public BalanceReadService(JdbcTemplate primary, JdbcTemplate replica,
                              SessionConsistencyRegistry registry) {
        this.primary = primary; this.replica = replica; this.registry = registry;
    }

    public BigDecimal balance(String userId, String accountId) {
        // If the user wrote recently, read from PRIMARY so they see their own change.
        if (registry.mustReadPrimary(userId)) {
            log.info("User {} within read-your-writes window → reading from PRIMARY", userId);
            return primary.queryForObject(
                "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
        }
        // Otherwise read from a REPLICA (slight staleness acceptable) to offload the primary.
        log.info("User {} outside window → reading from REPLICA", userId);
        return replica.queryForObject(
            "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
    }
}
